<?php require '../../../config/bootstrap.php';$u=require_auth();$p=db();if($_SERVER['REQUEST_METHOD']==='GET'){[$page,$per,$off]=paginate();$s=$p->prepare('SELECT id,farm_id,device_code,name,device_type,status,firmware_version,last_seen_at,created_at FROM devices WHERE tenant_id=? ORDER BY id DESC LIMIT ? OFFSET ?');$s->bindValue(1,$u['tenant_id'],PDO::PARAM_INT);$s->bindValue(2,$per,PDO::PARAM_INT);$s->bindValue(3,$off,PDO::PARAM_INT);$s->execute();json_response(['data'=>$s->fetchAll(),'page'=>$page,'per_page'=>$per]);}require_role($u,['owner','admin','manager']);require_csrf();$d=request_json();$code=trim((string)($d['device_code']??''));$name=trim((string)($d['name']??''));if($code===''||$name==='')json_response(['error'=>'device_code e name são obrigatórios'],422);$s=$p->prepare('INSERT INTO devices(tenant_id,farm_id,device_code,name,device_type,firmware_version) VALUES(?,?,?,?,?,?)');try{$s->execute([$u['tenant_id'],$d['farm_id']??null,$code,$name,$d['device_type']??'esp32',$d['firmware_version']??null]);$id=(int)$p->lastInsertId();$secret=bin2hex(random_bytes(24));$hash=hash_hmac('sha256',$secret,envv('DEVICE_KEY_PEPPER','change-me'));$p->prepare('INSERT INTO device_credentials(device_id,secret_hash) VALUES(?,?)')->execute([$id,$hash]);audit($u,'create','device',$id,['device_code'=>$code]);json_response(['id'=>$id,'device_code'=>$code,'device_secret'=>$secret],201);}catch(PDOException $e){if((int)$e->errorInfo[1]===1062)json_response(['error'=>'device_code já existe'],409);throw $e;}
